package br.com.mvdelivery.app;
import br.com.mvdelivery.repository.*; import br.com.mvdelivery.model.*;
import javax.swing.*; import javax.swing.table.*; import java.awt.*; import java.lang.reflect.*; import java.time.*; import java.math.*; import java.util.*;
public class MVDeliveryApp extends JFrame {
 private final Repository repo; private final JTabbedPane tabs=new JTabbedPane(); private final java.util.List<Panel> panels=new ArrayList<>();
 public MVDeliveryApp(Repository r){super("MV.Delivery | Gestão de entregas");repo=r;setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1060,650);setLocationRelativeTo(null);JLabel header=new JLabel("  MV.Delivery  |  Gestão de entregas");header.setOpaque(true);header.setBackground(new Color(23,51,75));header.setForeground(Color.WHITE);header.setFont(new Font("SansSerif",Font.BOLD,24));header.setPreferredSize(new Dimension(1,64));add(header,BorderLayout.NORTH);for(Schema s:Schema.values()){Panel p=new Panel(s);panels.add(p);tabs.addTab(s.title,p);}add(tabs);tabs.addChangeListener(e->refreshAll());refreshAll();}
 private void refreshAll(){for(Panel p:panels)p.refresh();}
 private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Não foi possível concluir",JOptionPane.ERROR_MESSAGE);}
 private class Panel extends JPanel {
  final Schema schema; final DefaultTableModel model;final JTable table;final JTextField search=new JTextField(22);final TableRowSorter<DefaultTableModel> sorter; java.util.List<Object> rows=new ArrayList<>();
  Panel(Schema s){super(new BorderLayout(10,10));schema=s;setBorder(BorderFactory.createEmptyBorder(15,15,15,15));model=new DefaultTableModel(s.labels,0){public boolean isCellEditable(int r,int c){return false;}};table=new JTable(model);table.setRowHeight(28);table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);sorter=new TableRowSorter<>(model);table.setRowSorter(sorter);JPanel bar=new JPanel(new FlowLayout(FlowLayout.LEFT));JLabel label=new JLabel("Buscar:");label.setLabelFor(search);bar.add(label);bar.add(search);search.getDocument().addDocumentListener(new javax.swing.event.DocumentListener(){public void insertUpdate(javax.swing.event.DocumentEvent e){filter();}public void removeUpdate(javax.swing.event.DocumentEvent e){filter();}public void changedUpdate(javax.swing.event.DocumentEvent e){filter();}});if(s!=Schema.HISTORICO){button(bar,"Novo",()->edit(false));button(bar,"Editar",()->edit(true));button(bar,"Excluir",()->remove());}button(bar,"Atualizar",()->refreshAll());add(bar,BorderLayout.NORTH);add(new JScrollPane(table));add(new JLabel(s==Schema.HISTORICO?"Histórico automático de pedidos.":"Selecione um registro para editar ou excluir."),BorderLayout.SOUTH);}
  void button(JPanel bar,String name,Runnable action){JButton b=new JButton(name);b.addActionListener(e->action.run());bar.add(b);}
  void filter(){sorter.setRowFilter(RowFilter.regexFilter("(?i)"+java.util.regex.Pattern.quote(search.getText())));}
  void refresh(){try{rows=repo.list(schema);model.setRowCount(0);for(Object o:rows){Object[] v=new Object[schema.fields.length];for(int i=0;i<v.length;i++)v[i]=schema.fields[i].get(o);model.addRow(v);}}catch(Exception e){model.setRowCount(0);}}
  Object selected(){int n=table.getSelectedRow();if(n<0)throw new IllegalArgumentException("Selecione um registro.");return rows.get(table.convertRowIndexToModel(n));}
  void remove(){try{Object o=selected();if(JOptionPane.showConfirmDialog(MVDeliveryApp.this,"Excluir o registro selecionado? Pedidos excluem histórico e feedback vinculados.","Confirmação",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION){repo.delete(schema,schema.id(o));refreshAll();}}catch(Exception e){error(e);}}
  void edit(boolean existing){try{Object o=existing?schema.copy(selected()):schema.create();JPanel form=new JPanel(new GridBagLayout());GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(5,5,5,5);g.fill=GridBagConstraints.HORIZONTAL;JComponent[] inputs=new JComponent[schema.fields.length];for(int i=1;i<inputs.length;i++){Field f=schema.fields[i];Class<?> t=f.getType();Object value=f.get(o);JComponent input;Schema rel=Schema.of(t);if(rel!=null){JComboBox<Object> box=new JComboBox<>();box.addItem(null);for(Object item:repo.list(rel)){box.addItem(item);if(value!=null&&rel.id(item)==rel.id(value))box.setSelectedItem(item);}input=box;}else if(t==StatusPedido.class){JComboBox<StatusPedido> box=new JComboBox<>(StatusPedido.values());if(value!=null)box.setSelectedItem(value);input=box;}else if(t==boolean.class){JCheckBox box=new JCheckBox("Sim",existing?(Boolean)value:true);input=box;}else{String def=value==null?"":value.toString();if(!existing&&t==LocalDateTime.class)def=LocalDateTime.now().withNano(0).toString();if(!existing&&f.getName().equals("nota"))def="5";input=new JTextField(def,28);}inputs[i]=input;JLabel l=new JLabel(schema.labels[i]+(f.getName().equals("observacoes")||f.getName().equals("comentario")||f.getName().equals("entregador")?"":" *"));l.setLabelFor(input);input.getAccessibleContext().setAccessibleName(schema.labels[i]);g.gridy=i;g.gridx=0;g.weightx=0;form.add(l,g);g.gridx=1;g.weightx=1;form.add(input,g);}while(JOptionPane.showConfirmDialog(MVDeliveryApp.this,form,(existing?"Editar ":"Novo registro - ")+schema.title,JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE)==JOptionPane.OK_OPTION){try{for(int i=1;i<inputs.length;i++){Field f=schema.fields[i];JComponent c=inputs[i];Object v;if(c instanceof JComboBox)v=((JComboBox<?>)c).getSelectedItem();else if(c instanceof JCheckBox)v=((JCheckBox)c).isSelected();else{String a=((JTextField)c).getText().trim();Class<?> t=f.getType();v=t==int.class?Integer.valueOf(a):t==BigDecimal.class?new BigDecimal(a.replace(',','.')):t==LocalDateTime.class?LocalDateTime.parse(a.replace(' ','T')):a;}f.set(o,v);}repo.save(schema,o);refreshAll();JOptionPane.showMessageDialog(MVDeliveryApp.this,"Registro salvo com sucesso.");break;}catch(Exception e){error(e);}}}catch(Exception e){error(e);}}
 }
 public static void main(String[] args){SwingUtilities.invokeLater(()->{UIManager.put("defaultFont",new Font("SansSerif",Font.PLAIN,14));try { if(Arrays.asList(args).contains("--memoria")){new MVDeliveryApp(new MemoryRepository()).setVisible(true);return;} java.util.Properties cfg=new java.util.Properties();try(java.io.InputStream in=new java.io.FileInputStream("config.properties")){cfg.load(in);}new MVDeliveryApp(new JdbcRepository(cfg.getProperty("url"),cfg.getProperty("user"),cfg.getProperty("password"))).setVisible(true); } catch(Exception ex){JOptionPane.showMessageDialog(null,"Falha na conexão MySQL: "+ex.getMessage()+"\nConfira config.properties e lib/mysql-connector-j.jar.","MV.Delivery",JOptionPane.ERROR_MESSAGE);}});}
}
